// LED trên ESP32 DevKit V1 nối GPIO 2
void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(115200);
  Serial.println("ESP32 bat dau nhay LED");
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);
  Serial.println("LED: BAT");
  delay(500);
  digitalWrite(LED_BUILTIN, LOW);
  Serial.println("LED: TAT");
  delay(500);
}
